    protected void createGenModelAnnotations() {
        String source = "http://www.eclipse.org/emf/2002/GenModel";
        this.addAnnotation((ENamedElement)this.actuatorHWEClass, source, new String[]{"documentation", "HW Element Actuator definition."});
        this.addAnnotation((ENamedElement)this.getActuatorHW_DefaultPositionType(), source, new String[]{"documentation", "Defines the way the actuator is seen after power on. On Bi-Stable or Multistable actuators the software has to know the status of this device after reset or Power On.\r\nEach actuator has a control input that determines its behaviour"});
        this.addAnnotation((ENamedElement)this.getActuatorHW_DefaultPositionValue(), source, new String[]{"documentation", "If there is a specific default value is available. E.g. Valve status = off;"});
        this.addAnnotation((ENamedElement)this.getActuatorHW_ElectricalType(), source, new String[]{"documentation", "Defines the most typical electrical behaviour of the system. This information is necessary for the ECU generation process and for tools which check for later interaction of the different component. (avoid resonance's, planning of the ECU power management)."});
        this.addAnnotation((ENamedElement)this.getActuatorHW_Endurance(), source, new String[]{"documentation", "Number of activation cycles the actuator is designed for."});
        this.addAnnotation((ENamedElement)this.getActuatorHW_Movement(), source, new String[]{"documentation", "Defines the way the movement is controlled by AUTOSAR. Positional feedback can be provided by the actuator by the conglomeration of the requisite actuator and sensor primitives.\r\n"});
        this.addAnnotation((ENamedElement)this.sensorActuatorHWEClass, source, new String[]{"documentation", "The common attributes for sensors and actuators.\r\nThe sensor and actuators can be connected via a Peripheral HW Port, a Communication HW Port or a Power Driver HW Port."});
        this.addAnnotation((ENamedElement)this.getSensorActuatorHW_Accuracy(), source, new String[]{"documentation", "Defines the error in the representation of the Technical Signal in the data format\r\nThis applies only if the Technical Signal is encoded before it is transferred to the ECU Electronics (e.g. via Communication Transceiver HW Port)."});
        this.addAnnotation((ENamedElement)this.getSensorActuatorHW_CycleTime(), source, new String[]{"documentation", "The time the sensor/actuator must be accessed for correct information. It is possible to give a minimum, a maximum and a typical cycle time."});
        this.addAnnotation((ENamedElement)this.getSensorActuatorHW_Resolution(), source, new String[]{"documentation", "Defines the granularity of the representation of the Technical Signal in the data format.\r\nThis applies only if the Technical Signal is encoded before it is transferred to the ECU Electronics (e.g. via Communication Transceiver HW Port)."});
        this.addAnnotation((ENamedElement)this.getSensorActuatorHW_Type(), source, new String[]{"documentation", "Defines the general type of the sensor/actuator type is a most common naming for a sensor/actuator and is an open list and is not restricted to the following items. Several sets of types exist. Type is mandatory for the usage of the template\r\n- Sensor: Temperature, Pressure, Distance, Hall\r\n- Actuator: DC Motor, Valve, Relay, Display"});
        this.addAnnotation((ENamedElement)this.actuatorHwElectricalTypeEnumEEnum, source, new String[]{"documentation", "Defines the most typical electrical behaviour of the system. This information is necessary for the ECU generation process and for tools which check for later interaction of the different component. (avoid resonance's, planning of the ECU power management).\r\n"});
        this.addAnnotation((ENamedElement)this.actuatorHwElectricalTypeEnumEEnum.getELiterals().get(0), source, new String[]{"documentation", "Heater, Lamp\r\n"});
        this.addAnnotation((ENamedElement)this.actuatorHwElectricalTypeEnumEEnum.getELiterals().get(1), source, new String[]{"documentation", "Extra SuperCAPS for bordnet stability"});
        this.addAnnotation((ENamedElement)this.actuatorHwElectricalTypeEnumEEnum.getELiterals().get(2), source, new String[]{"documentation", "Coils, Motor"});
        this.addAnnotation((ENamedElement)this.actuatorHwMovementEnumEEnum, source, new String[]{"documentation", "Defines the way the movement is controlled by AUTOSAR. Positional feedback can be provided by the actuator by the conglomeration of the requisite actuator and sensor primitives."});
        this.addAnnotation((ENamedElement)this.actuatorHwMovementEnumEEnum.getELiterals().get(0), source, new String[]{"documentation", "The actuator is only forced in one direction by SW. e.g. eject of a tape. The user or a other mechanical system is needed to chance the status of the actuator. Other example is a motor which has a circular movement always in one direction. SW can not alter this behaviour e.g. fan, wiper."});
        this.addAnnotation((ENamedElement)this.actuatorHwMovementEnumEEnum.getELiterals().get(1), source, new String[]{"documentation", "The actuator can be moved forward and backward by software, e.g. window lift\r\n"});
        this.addAnnotation((ENamedElement)this.actuatorHwMovementEnumEEnum.getELiterals().get(2), source, new String[]{"documentation", "Unidirectional with autoreset: The actuator is controlled only one direction by electrical means and SW. Bringing the actuator in to the default position other means are available. E.g. unlock of the trunk or gasoline flap with a motor which is brought into the initial position with a spring; a relay or a valve use the same mechanism."});
        this.addAnnotation((ENamedElement)this.actuatorHwDefaultPositioinTypeEnumEEnum, source, new String[]{"documentation", "Defines the way the actuator is seen after power on. On Bi-Stable or Multistable actuators the software has to know the status of this device after reset or Power On.\r\nEach actuator has a control input that determines its behaviour"});
        this.addAnnotation((ENamedElement)this.actuatorHwDefaultPositioinTypeEnumEEnum.getELiterals().get(0), source, new String[]{"documentation", "The actuator has a unique defined position after a reset or power down. E.g. a spring force the actuator back into a start position or there are means which give a position feedback like a potentiometer or switch."});
        this.addAnnotation((ENamedElement)this.actuatorHwDefaultPositioinTypeEnumEEnum.getELiterals().get(1), source, new String[]{"documentation", "The position of the actuator can not be specified after power on or reset or the position of the actuator can be changed by other means"});
        this.addAnnotation((ENamedElement)this.actuatorHwDefaultPositioinTypeEnumEEnum.getELiterals().get(2), source, new String[]{"documentation", "The actuator has two possible, defined positions after a reset or power down. E.g. the actuator is in one of the two possible end positions. Only one of them is signalled by a feedback, e.g. a switch. The second end position is simply to be determined as the inversion of the feedback.\r\n"});
        this.addAnnotation((ENamedElement)this.actuatorHwDefaultPositioinTypeEnumEEnum.getELiterals().get(3), source, new String[]{"documentation", "The actuator has more possible, defined positions after a reset or power down and they are signalled by appropriate feedback E.g. a door latch might consist of different stable states: pre-locked, locked, double locked, released, open from outside, open from inside, All this states are covered by a feedback, and the states can change in random manner after the wake-up or power-up of a car."});
        this.addAnnotation((ENamedElement)this.displayHWEClass, source, new String[]{"documentation", "The Display HW element derives from HW Sensor Actuator and can be connected to a PU via a serial or parallel interface.\r\nFor the parallel mode the display can be connected to the data bus and address bus of a PU or to a peripheral.\r\nThe most common serial interface for displays are:\r\n- I2C\r\n- SPI\r\nThe most common physical interface for high resolution displays are the LVDS interface (Low Voltage Differential Signalling). This interface has three different lines for colours (RGB) and additional lines for control signals."});
        this.addAnnotation((ENamedElement)this.getDisplayHW_Backlight(), source, new String[]{"documentation", "Defines whether the display has a background lighting. This eases the readability of the displays during bad daylight conditions."});
        this.addAnnotation((ENamedElement)this.getDisplayHW_Brightness(), source, new String[]{"documentation", "Defines the visibility of the display."});
        this.addAnnotation((ENamedElement)this.getDisplayHW_BtypeOfCharacters(), source, new String[]{"documentation", "If the display can present numerical, alpha-numerical, semi-graphical or graphical objects."});
        this.addAnnotation((ENamedElement)this.getDisplayHW_CharacterGenerator(), source, new String[]{"documentation", "If the display has an in-built character generator."});
        this.addAnnotation((ENamedElement)this.getDisplayHW_CharacterSet(), source, new String[]{"documentation", "Defines which character set that can be handled by the display. There is a number of standardised character sets like ISO-8859-1 or Unicode."});
        this.addAnnotation((ENamedElement)this.getDisplayHW_Colour(), source, new String[]{"documentation", "If the display can show objects in monochrome, grey scale or in colour."});
        this.addAnnotation((ENamedElement)this.getDisplayHW_ResolutionRation(), source, new String[]{"documentation", "Defines the ratio of the display resolution in horizontal versus vertical direction (e.g. 16 to 9)."});
        this.addAnnotation((ENamedElement)this.getDisplayHW_ResolutionX(), source, new String[]{"documentation", "Defines the number of the smallest graphical elements which can be displayed in horizontal direction."});
        this.addAnnotation((ENamedElement)this.getDisplayHW_ResolutionY(), source, new String[]{"documentation", "Defines the number of the smallest graphical elements which can be displayed in vertical direction."});
        this.addAnnotation((ENamedElement)this.getDisplayHW_ResponseTime(), source, new String[]{"documentation", "Defines how long it takes for the display to show a changed element at -20 degree C."});
        this.addAnnotation((ENamedElement)this.getDisplayHW_ViewingAngle(), source, new String[]{"documentation", "Defines the angle range where the display can be observed."});
        this.addAnnotation((ENamedElement)this.displayHwColourEnumEEnum, source, new String[]{"documentation", "If the display can show objects in monochrome, grey scale or in colour."});
        this.addAnnotation((ENamedElement)this.displayHwTypeOfCharactersEnumEEnum, source, new String[]{"documentation", "If the display can present numerical, alpha-numerical, semi-graphical or graphical objects."});
        this.addAnnotation((ENamedElement)this.sensorHWEClass, source, new String[]{"documentation", "HW Element Sensor definition."});
        this.addAnnotation((ENamedElement)this.getSensorHW_SignalQuality(), source, new String[]{"documentation", "Defines the quality of the data received from a sensor. Depending on this information later processing on the signal has to be done in HW or SW."});
        this.addAnnotation((ENamedElement)this.sensorHwSignalQualityEnumEEnum, source, new String[]{"documentation", "Defines the quality of the data received from a sensor. Depending on this information later processing on the signal has to be done in HW or SW."});
        this.addAnnotation((ENamedElement)this.sensorHwSignalQualityEnumEEnum.getELiterals().get(0), source, new String[]{"documentation", "The information are transferred without any signal processing from the sensor to the according electronic. Possible spikes and noise is present on the line. In order to use this signal an appropriate signal processing have to be performed."});
        this.addAnnotation((ENamedElement)this.sensorHwSignalQualityEnumEEnum.getELiterals().get(1), source, new String[]{"documentation", "The information passed some filter mechanism in order to remove noise and spikes from the signal.  The signal can be in a discrete form, At least the limit e.g. the -3dB limit, must be available to the software if this limit is close to the used bandwidth, needed for the planed application.  If more complex filter like bandpasses or notch filter are used the filter characteristic must be modelled and imported for the according SW-Component as well."});
        this.addAnnotation((ENamedElement)this.sensorHwSignalQualityEnumEEnum.getELiterals().get(2), source, new String[]{"documentation", "The information was already processed by some electronics in order to get a clear and unique representation of the information. Debouncing is a sort of filter which suppress the noises and spikes which are generated by the bouncing when a switch is opened or closed. Debouncing is similar to Filtered, but the input is only represented by digital values instead of analogue values.\r\nTypical debouncing electronics are mono- flops or sampling , plus a majority encoder to represent a more stable signal.\r\n"});
        this.addAnnotation((ENamedElement)this.sensorHwSignalQualityEnumEEnum.getELiterals().get(3), source, new String[]{"documentation", "The information is filtered and debounced, but furthermore represented in a digital encoded form.\r\nExamples are sensor connected via a serial communication bus like LIN to the ECU.\r\nIt must be noted that the complexity of the ECU will have a concomitant effect on the complexity of the corresponding ECU SW abstraction. Generally the more complex the ECU electronics, the more complex the abstract interfaces will be for the user to configure."});
    }

